INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist ein ERD nur für relationale Datenbanken relevant?', 2, '[{"text": "Ja", "correct": true, "because": "Speziell für Tabellen und Schlüssel"}, {"text": "Nein", "correct": false, "because": "Hauptfokus auf relationale DBs"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit einem ERD?', 3, '[{"text": "Datenbankimplementierung visualisieren", "correct": true, "because": "Zeigt Tabellen und Beziehungen"}, {"text": "Datenfluss darstellen", "correct": false, "because": "Datenflussdiagramm-Thema"}, {"text": "UI gestalten", "correct": false, "because": "Kein Designaspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören zu einem ERD?', 5, '[{"text": "Tabellen", "correct": true, "because": "Repräsentieren Entitäten"}, {"text": "Schlüssel", "correct": true, "because": "Definieren Beziehungen"}, {"text": "Farbanimation", "correct": false, "because": "Irrelevant"}, {"text": "Prozessfluss", "correct": false, "because": "Aktivitätsdiagramm"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) ERDs zeigen Primärschlüssel. b) Sie ersetzen Programmablaufpläne.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Abläufe sind Programmablaufpläne"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei einem ERD?', 4, '[{"text": "Tabellenbeziehungen", "correct": false, "because": "Kern des Diagramms"}, {"text": "Fremdschlüssel", "correct": false, "because": "Verbinden Tabellen"}, {"text": "Grafische Effekte", "correct": true, "because": "Kein Modellierungsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein ERD auch Prozesse zeigt?', 2, '[{"text": "Nein", "correct": true, "because": "Fokus auf Datenstruktur"}, {"text": "Ja", "correct": false, "because": "Prozesse in anderen Diagrammen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element wähle ich für eine Tabelle im ERD?', 3, '[{"text": "Rechteck", "correct": true, "because": "Standard für Entitäten"}, {"text": "Pfeil", "correct": false, "because": "Nur Beziehungen"}, {"text": "Kreis", "correct": false, "because": "Andere Diagramme"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Komponenten gehören zu einem ERD?', 5, '[{"text": "Primärschlüssel", "correct": true, "because": "Identifizieren Datensätze"}, {"text": "Fremdschlüssel", "correct": true, "because": "Verbinden Tabellen"}, {"text": "Datenfluss", "correct": false, "because": "Datenflussdiagramm"}, {"text": "UI-Layout", "correct": false, "because": "Kein Implementierungsaspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) ERDs sind für Datenbankdesign entscheidend. b) Sie zeigen dynamische Abläufe. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Abläufe sind Aktivitätsdiagramm"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für ein ERD?', 4, '[{"text": "Tabellen", "correct": false, "because": "Kern der Struktur"}, {"text": "Beziehungen", "correct": false, "because": "Verbinden Entitäten"}, {"text": "Prozessschritte", "correct": true, "because": "Programmablaufplan-Thema"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist ein ERD rein konzeptionell?', 2, '[{"text": "Nein", "correct": true, "because": "Implementierungsspezifisch"}, {"text": "Ja", "correct": false, "because": "Visuelle Darstellung des ERM"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Beziehungen zeigt ein ERD?', 4, '[{"text": "1:n", "correct": true, "because": "Ein-zu-viele Beziehungen"}, {"text": "n:m", "correct": true, "because": "Viele-zu-viele mit Verbindungstabelle"}, {"text": "Datenfluss", "correct": false, "because": "Datenflussdiagramm"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ERDs nur für Designer sind. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für Entwickler und DB-Admins"}, {"text": "Ja", "correct": false, "because": "Breitere Nutzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei einem ERD?', 3, '[{"text": "Klarheit der Beziehungen", "correct": true, "because": "Fördert Verständnis"}, {"text": "Schnelle Erstellung", "correct": false, "because": "Genauigkeit zählt"}, {"text": "Visuelle Effekte", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) ERDs zeigen Tabellenbeziehungen. b) Sie sind für NoSQL-Datenbanken ideal.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "NoSQL weniger tabellenorientiert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein ERD?', 5, '[{"text": "Datenbankübersicht", "correct": true, "because": "Klarheit über Struktur"}, {"text": "Beziehungsplanung", "correct": true, "because": "Schlüssel sichtbar"}, {"text": "Datenflussanalyse", "correct": false, "because": "Datenflussdiagramm"}, {"text": "UI-Design", "correct": false, "because": "Kein Designaspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einem ERD unwichtig?', 3, '[{"text": "Tabellenattribute", "correct": false, "because": "Definieren Daten"}, {"text": "Schlüsselbeziehungen", "correct": false, "because": "Verbinden Tabellen"}, {"text": "Blinkende Anzeige", "correct": true, "because": "Kein Implementierungsaspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Zeigt ein ERD auch Prozessabläufe?', 3, '[{"text": "Nein", "correct": true, "because": "Fokus auf Struktur"}, {"text": "Ja", "correct": false, "because": "Abläufe in anderen Diagrammen"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein ERD für Tests nützlich ist?', 2, '[{"text": "Ja", "correct": true, "because": "Basis für Datenbanktests"}, {"text": "Nein", "correct": false, "because": "Testfälle ableitbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Symbol wähle ich für eine Beziehung im ERD?', 4, '[{"text": "Linie mit Kardinalität", "correct": true, "because": "Zeigt Beziehungsart"}, {"text": "Rechteck", "correct": false, "because": "Nur Tabellen"}, {"text": "Pfeil", "correct": false, "because": "Andere Diagramme"}]');
